const $=id=>document.getElementById(id), names={mountain:'山型',valley:'谷型',trapezoid:'台形',curve:'曲線'}, methods={keep:['↻','反転しない'],reflect:['⇄','反転する']};
let state={shape:'square',mods:[],count:0},selection={edge:null,range:'whole',pattern:'mountain',height:'normal',symmetric:true,method:'keep'},past=[],future=[],background='white',tileColor='#65cdb6',preview=false,busy=false,notice='';
